import {validGameplayTag,hasGameplayTag} from './scene-systems.js';
export const gameplayCuePhases=Object.freeze(['activate','end','apply','period','remove','blocked','inhibit','resume']);
const soundPath=value=>typeof value==='string'&&value.length<=1000&&(value===''||/^Assets\/(?:[^/\\:\x00-\x1f]+\/)*[^/\\:\x00-\x1f]+\.(?:hbaudioasset\.json|wav|ogg|mp3|flac)$/i.test(value)&&!value.split('/').some(p=>p==='.'||p==='..'));
export function createGameplayCue(name){return{version:1,name,routes:[]};}
export function gameplayCueRoute(index){return{id:'route'+index,tag:'Cue.New'+index,exact:false,on:'apply',action:'play',channel:'main',sound:'',volume:1,pitch:1,spatial:true,emitCount:0};}
export function nextGameplayCueRoute(rows){const used=new Set(rows.map(row=>row.id));let index=1;while(used.has('route'+index))index++;return gameplayCueRoute(index);}
export function validGameplayCue(data){return data?.version===1&&typeof data.name==='string'&&data.name.length>0&&data.name.length<=80&&!/[\x00-\x1f]/.test(data.name)&&Array.isArray(data.routes)&&new Set(data.routes.map(row=>row?.id)).size===data.routes.length&&data.routes.every(r=>r&&typeof r.id==='string'&&/^[A-Za-z_][\w-]{0,79}$/.test(r.id)&&validGameplayTag(r.tag)&&typeof r.exact==='boolean'&&gameplayCuePhases.includes(r.on)&&['play','stop'].includes(r.action)&&typeof r.channel==='string'&&/^[\w가-힣.-]{1,80}$/.test(r.channel)&&soundPath(r.sound)&&Number.isFinite(r.volume)&&r.volume>=0&&r.volume<=4&&Number.isFinite(r.pitch)&&r.pitch>=.1&&r.pitch<=4&&typeof r.spatial==='boolean'&&Number.isSafeInteger(r.emitCount)&&r.emitCount>=0&&r.emitCount<=100000);}
export function matchingGameplayCues(program,args){return (program.byPhase?.[args.phase]||program.routes).filter(row=>row.on===args.phase&&(row.exact?row.tag===args.tag:hasGameplayTag([args.tag],row.tag)));}
export async function loadGameplayCueProgram(path,read){if(typeof path!=='string'||!/^Assets\/.+\.hbgameplaycue\.json$/.test(path)||path.split('/').some(p=>p==='.'||p==='..')||/[\\:\x00-\x1f]/.test(path))throw Error('게임플레이 Cue 자산 경로를 확인하세요.');const data=await read(path);if(!validGameplayCue(data))throw Error('게임플레이 Cue 자산 검증 실패: '+path);const routes=Object.freeze(data.routes.map(row=>Object.freeze({...row})));return Object.freeze({path,routes,byPhase:Object.freeze(Object.fromEntries(gameplayCuePhases.map(phase=>[phase,Object.freeze(routes.filter(row=>row.on===phase))])))});}
export class GameplayCueLibrary {
 constructor(read){this.read=read;this.cache=new Map();}
 load(path){if(!this.cache.has(path))this.cache.set(path,loadGameplayCueProgram(path,this.read).catch(error=>{this.cache.delete(path);throw error;}));return this.cache.get(path);}
 clear(){this.cache.clear();}
}
export const gameplayCueContract={asset:'gameplaycue / .hbgameplaycue.json v1',component:'AbilitySystem.cueAsset',phases:gameplayCuePhases,matching:'Hierarchical cue tag by default; exact optional. All matching routes run in authored order after the ability/effect transaction commits.',media:'One-shot ordinary audio asset/local media, volume/pitch/spatial, voice scoped by owner generation + effect/ability + channel. Stop route cancels only that channel. Particle burst uses the owner’s existing enabled ParticleSystem.',lifetime:'Existing audio async owner/VM guards and particle owner lifetime. Captured generation prevents events from binding to replacement IDs. No idle timer, per-event Cue routing-file IO or new object pool. Ordinary audio loading retains its existing behavior.',rebinding:'Existing componentSetString / C++ component string setter reloads a different cueAsset through fresh validated IO; same path is an IO-free no-op. Latest accepted request wins. Failed/stale loads keep prior property/program; unrelated property edits survive. Old program channels/pending audio and factory bursts are retired, active/inactive owner lifetimes remain guarded.',editing:'Existing asset creation/structured routes, document.patch/CAS/dryRun/Undo/save and dependency cook. Empty route is an authored no-op.',failures:'Route media failure reported in gameplayDebug.cues and existing log; committed gameplay values/custom Cue event remain available.',limits:['Standalone VFX template spawning/attachment','Per-emitter-component selection and persistent VFX stop handles','Network Cue prediction/replication','OS audio/visual validation remains separate']};
